"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[916],{60916:e=>{e.exports=JSON.parse('{"slug":"uyazvimost-php2shell-sayty-bankov-oktyabr-2026","locale":"ru","title":"Из-за уязвимости в PHP ФСБ предписала банкам и госорганам отключать сайты, которые не успели обновить","description":"В PHP нашли две критические уязвимости. ФСБ предписала банкам и госорганам обновиться или отключить сайты. Почему одна ошибка бьёт по всему интернету.","blocks":[{"id":"b001","kind":"paragraph","text":"21 октября разработчики PHP выпустили исправления двух уязвимостей, их назвали PHP2Shell. Обе получили оценку опасности 9,2 из 10. Через них злоумышленник одним запросом без пароля может выполнить свой код на сервере и получить доступ к данным. Раскрыть детали планировали позже, но они утекли в сеть раньше. Первую попытку атаки ловушка Amazon заметила 17 октября, за 4 дня до исправления. Исследователи Wiz считают, что ошибкам десятки лет, а превратить их в рабочий взлом помогли современные модели искусственного интеллекта."},{"id":"b002","kind":"paragraph","text":"22 октября Национальный координационный центр по компьютерным инцидентам при ФСБ разослал письмо через ГосСОПКА, систему обнаружения компьютерных атак. Письмо получили объекты критической информационной инфраструктуры: госорганы, финансовые, энергетические, транспортные и медицинские организации. Им предписано обновить PHP и проверить серверы антивирусом. Если быстро обновиться нельзя, нужно ограничить внешний доступ к уязвимым серверам или отключить их."},{"id":"b003","kind":"paragraph","text":"Представим город, где почти все подъезды закрыты замками одной фирмы. Однажды выясняется, что к ним подходит один ключ, и копия ключа уже ходит по рукам. Менять замки придётся всем одновременно, и пока мастер не пришёл, подъезд безопаснее держать закрытым изнутри. Экономисты называют это системным риском: когда все пользуются одним решением, его сбой бьёт по всем сразу. PHP бесплатный и удобный, поэтому на нём работает большая часть интернета, и поэтому одна ошибка в нём превращается в общую проблему."},{"id":"b004","kind":"paragraph","text":"В других странах сайты уже отключали. В Британии временно закрыли 32 государственных сервиса, власти объяснили это мерой предосторожности на время обновления. Недоступны были и государственные сайты Бельгии, Нидерландов, Финляндии, Франции и Германии. Компании по кибербезопасности сообщают о миллионах попыток использовать уязвимость. Данных о массовых отключениях или взломах в России пока нет."},{"id":"b005","kind":"paragraph","text":"Для пользователей это значит, что сайт банка, госоргана или личный кабинет может на время перестать открываться. Само по себе это не признак взлома: организация закрывает доступ, пока ставит исправление. Для компании отключение стоит упущенных продаж и недовольных клиентов. Взлом стоит дороже: утечка данных, штрафы, украденные деньги и восстановление систем. Поэтому центр при ФСБ и выбирает короткий простой."},{"id":"b006","kind":"paragraph","text":"Сколько займёт обновление, зависит от организации. Крупные банки с отлаженными процессами могут поставить исправления за часы. Небольшие компании и сайты на старых версиях PHP, которые разработчики уже не поддерживают, могут остаться уязвимыми надолго. Масштаб успешных взломов станет ясен позже, когда компании проверят журналы. Короткие перебои в работе сайтов в ближайшие дни чаще всего значат, что исправление ставят. Опаснее необновлённый сервер, который продолжает работать как ни в чём не бывало."},{"id":"b007","kind":"heading","text":"Что такое уязвимость PHP2Shell?"},{"id":"b008","kind":"paragraph","text":"Это две ошибки в языке программирования PHP, CVE-2026-109618 и CVE-2026-109619, с оценкой опасности 9,2 из 10. Через них злоумышленник одним запросом без пароля может выполнить свой код на сервере сайта и получить доступ к данным. Исправление вышло 21 октября 2026 года."},{"id":"b009","kind":"heading","text":"Будут ли не работать сайты банков и госорганов?"},{"id":"b010","kind":"paragraph","text":"Возможно, на время обновления. 22 октября центр при ФСБ предписал объектам критической инфраструктуры, в том числе банкам и госорганам, срочно обновить PHP, а если быстро не получается, ограничить доступ к сайтам или отключить их. Данных о массовых отключениях в России пока нет."},{"id":"b011","kind":"heading","text":"Почему одна ошибка затронула столько сайтов?"},{"id":"b012","kind":"paragraph","text":"PHP используют около 70% сайтов мира и больше 90% русскоязычных. Когда у миллионов сайтов общий фундамент, одна ошибка в нём открывает их все сразу, и каждому владельцу нужно ставить исправление самому."}],"sources":[{"label":"РБК. ФСБ рекомендовала отключать сайты из-за уязвимости в PHP","url":"https://www.kommersant.ru/doc/9045269"},{"label":"Центр при ФСБ предписал отключать сайты из-за уязвимости в PHP","url":"https://frankmedia.ru/311764"},{"label":"PHP2Shell. Critical PHP vulnerabilities patched, update now","url":"https://www.helpnetsecurity.com/2026/10/21/php2shell-php-vulnerabilities-patched-cve-2026-109618-cve-2026-109619/"},{"label":"PHP2Shell. Mass Exploitation Looms for Leaked Critical PHP Flaws","url":"https://www.securityweek.com/php2shell-mass-exploitation-looms-for-leaked-critical-php-flaws/"},{"label":"Websites across world hit by millions of attempts to exploit PHP code flaw","url":"https://www.theguardian.com/technology/2026/oct/22/websites-across-world-hit-by-millions-of-attempts-to-exploit-php-code-flaw"},{"label":"PHP2Shell puts dozens of UK government services out of service","url":"https://www.theregister.com/security/2026/10/22/php2shell-puts-dozens-of-uk-government-services-out-of-service/5304840"},{"label":"Выявленные с помощью ИИ две уязвимости в веб-безопасности вызвали тревогу в мире","url":"https://www.forbes.ru/tekhnologii/570823-vyavlennye-s-pomos-u-ii-dve-uazvimosti-v-veb-bezopasnosti-vyzvali-trevogu-v-mire"}],"sourceBodySha256":"e3fb2a77720fe8860c329873f043e4f7761ab7ab4c70849c9068a88ee60dd68e"}')}}]);